INSERT INTO "fact" VALUES('interp:AQ14102629:pccc2308c1b','pccc2308c1b','interpellation','2026-09-24','{"councillors": ["侯漢廷"], "dept": "民政", "doc_no": "AQ14102629", "doc_type": "書面質詢", "session": "第14屆第08次定期大會", "term": 14, "title": "受監護長者財產遭侵占案凸顯社會局內控機制失靈，應全面檢討財產管理及監督制度"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDF4D1149F9F07E2CCF956DF52FFFF6CDEB1819EADFBF58901D53A4C1421580216D8309A9A54DE7DF3','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14102628:pea1a4317b4','pea1a4317b4','interpellation','2026-09-24','{"councillors": ["王欣儀"], "dept": "教育", "doc_no": "AQ14102628", "doc_type": "書面質詢", "session": "第14屆第08次定期大會", "term": 14, "title": "運動中心預約期限因付款方式不同形成落差；U-Sport運動抵用金無法線上折抵，影響民眾使用權益！"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDF4D1149F9F07E2CC56A45A75C0FA2FF43910BE50B21CB9BED53A4C142158021675117A70A35C59F0','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14102627:p06dbec1b42','p06dbec1b42','interpellation','2026-09-24','{"councillors": ["郭昭巖"], "dept": "教育", "doc_no": "AQ14102627", "doc_type": "書面質詢", "session": "第14屆第08次定期大會", "term": 14, "title": "校園跑道破損、東園社宅久候未成，公共建設不能只編預算、排期程。本席要求市府加速推動116年度12校運動場及跑道工程，並檢討東園社宅施工期程與公共服務空間配置，讓建設真正符合學生及地方居民需求。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDF4D1149F9F07E2CCC4AA15759007B99F1C3875E7036378B4D53A4C1421580216DEBF390FBCBDCC43','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14102624:p47f1fe2e84','p47f1fe2e84','interpellation','2026-09-23','{"councillors": ["李明賢"], "dept": "交通", "doc_no": "AQ14102624", "doc_type": "書面質詢", "session": "第14屆第08次定期大會", "term": 14, "title": "針對改善公車駕駛勞動環境，解決「工時過長」與落實「完整教育訓練」兩大核心痛點之具體檢討與配套問題"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDF4D1149F9F07E2CC2CB05844BABC6848E5B0201176842E30D53A4C1421580216569641D4312D3101','2026-09-28T10:12:56Z');
