INSERT INTO "fact" VALUES('interp:AQ14101945:p155e15fe02','p155e15fe02','interpellation','2025-09-24','{"councillors": ["張志豪"], "dept": "警政衛生", "doc_no": "AQ14101945", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "114年9月23日，花蓮縣光復鄉發生重大災害，社會關切為何台北市義消特搜隊並未出勤支援。經查，台北市警消已出勤，其他縣市如：新北市接獲花蓮救災訊息，則警義消同時出動。然而台北市義消特搜隊係由台北市搜救隊訓練並逐年考核，不僅是市府重要的民力支援能量，更代表具備國際標準的專業救援能力(台北市搜救隊已通過消防署 NAP（National Accreditation Process）認證為重型搜救隊)。在「全民防災、民力運用」的概念下，如何調度、啟動，以及向市民清楚說明此隊伍的角色定位，攸關首都守備與全國救災能量整合，值得本會深入監督。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDCF28F828E4CD48717ED9DD5A68A3042C381EECC434E4866062F3DF37482B742031EC370CA9BB3E4E','2026-09-28T10:12:56Z');
