INSERT INTO "fact" VALUES('interp:AQ14101941:p155e15fe02','p155e15fe02','interpellation','2025-09-22','{"councillors": ["張志豪"], "dept": "財政建設", "doc_no": "AQ14101941", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "翡翠水庫延長水力發電支援供電之影響與回饋機制。據報載2025年9月18日，林口火力發電廠兩部機組故障停機，台電公司緊急請求支援。翡翠水庫水力電廠臨時將日發電時數自 11 小時延長為 15 小時；翡翠水庫是大台北 600 萬人口的主要飲用水源，若調度不當，恐影響民生用水安全。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDCF28F828E4CD4871F73DAA2AAD56F0ED12D54E15A0BEAFB962F3DF37482B74201D7EE3FBC4AA42FD','2026-09-28T10:12:56Z');
