INSERT INTO "fact" VALUES('interp:AQ14101757:p155e15fe02','p155e15fe02','interpellation','2025-06-27','{"councillors": ["張志豪"], "dept": "交通", "doc_no": "AQ14101757", "doc_type": "書面質詢", "session": "第14屆第07次臨時大會", "term": 14, "title": "高齡職業駕駛風險管理與吊車行駛管制之市政責任檢討。113年6月21日下午於本市大安區新生南路與忠孝東路口，發生吊車衝撞三輛機車之重大交通事故，造成年僅18歲之蔡姓女學生當場身亡。事故駕駛為77歲賴姓男子，事後未即時停車並繼續前行，經檢方偵辦後15萬元交保，社會輿論譁然。為釐清市府對職業駕駛肇事管理與吊車行車風險控管責任，特提出如下質詢。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDCF28F828E4CD48713526560A0695A56B5D3F17206CE314A962F3DF37482B742082E248607768E9CB','2026-09-28T10:12:56Z');
