INSERT INTO "fact" VALUES('interp:AQ14101583:p155e15fe02','p155e15fe02','interpellation','2025-03-17','{"councillors": ["張志豪"], "dept": "財政建設", "doc_no": "AQ14101583", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "請臺北市動保處說明近期比特犬連續傷人事件之處置情形與未來管理對策。近日媒體報導，臺北市發生兩起相同比特犬攻擊機車騎士的事件，分別發生於3月6日及3月17日，案件細節如下：3月6日，該比特犬在臺北市文山區自行打開車窗，衝出車外攻擊一名機車騎士，造成騎士腿部受傷。3月17日，同一隻比特犬在大安區臥龍街，再度自行打開車窗跳出車外，攻擊機車騎士，造成其中一名騎士腿部嚴重受傷。兩次案件均由同一飼主所飼養，且犬隻均在車內自行開啟車窗後衝出傷人，顯示飼主對犬隻之控管存有嚴重問題。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDCF28F828E4CD48715FC026ABF6B40196199C07A487E70B4162F3DF37482B74209E654906E1963FB2','2026-09-28T10:12:56Z');
