INSERT INTO "fact" VALUES('interp:AQ14101478:pc50235ea45','pc50235ea45','interpellation','2025-02-03','{"councillors": ["顏若芳"], "dept": "警政衛生", "doc_no": "AQ14101478", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "本市員警誤餐費曾於2024年曾配合警政署修正調升，然現行早餐、夜點之誤餐費仍無法追上消費者物價上升幅度，甚至低於本市消防員誤餐費基準，本席認為，警、消誤餐費均過低應同步調升，故請警察局、消防局儘速與中央溝通，或自編預算調升誤餐費，以加強照顧本市基層員警、消防員。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDCF28F828E4CD4871F8A9372122F109738DD39018B4C5B67562F3DF37482B7420E92B554DA37A558C','2026-09-28T10:12:56Z');
