INSERT INTO "fact" VALUES('interp:AQ14101467:p072095ef7a','p072095ef7a','interpellation','2025-01-15','{"councillors": ["李芳儒"], "dept": "民政", "doc_no": "AQ14101467", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "為避免臺北市老人福利機構供需比例失衡長者需要候位很久的時間才能進住，進而導致家庭照顧者的負擔。本席要求臺北市政府原住民族事務委員會(以下簡稱原民會)應開放設籍臺北市原住民長者在新北市已立案之老人福利機構進住，減輕其家庭照顧者的負擔，實現對原住民高齡者全方位的照護支持。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDCF28F828E4CD487101DEF42EB36D8FEEB3BA211A3305417362F3DF37482B742010B6D5CD2DEE6B19','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101466:p155e15fe02','p155e15fe02','interpellation','2025-01-15','{"councillors": ["張志豪"], "dept": "工務", "doc_no": "AQ14101466", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "師大路和平東路口路樹倒塌事件(發生日114年1月11日)調查與責任檢討。本次路樹倒塌事件不僅可能威脅市民安全，也暴露出台北市在施工管理與環境保護上的制度性缺陷。建議市府應全面檢討政策與管理流程，強化樹木保護與施工規範的執行力，並以公開透明的方式向市民交代責任與改進措施，確保市政建設與環境永續並行。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDCF28F828E4CD4871288D09EBEBF892B13BE550597D96711662F3DF37482B742038A0C095B4E2511F','2026-09-28T10:12:56Z');
