INSERT INTO "fact" VALUES('interp:AQ14101267:pc50235ea45','pc50235ea45','interpellation','2024-09-30','{"councillors": ["顏若芳"], "dept": "工務", "doc_no": "AQ14101267", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "本市於22日發生短時強降雨，導致大龍峒社宅頂樓排水不及甚至淹水至一樓大廳，亦引發各界對於本市社宅排水機制、施工品質之質疑，故本席要求貴府應全面盤點本市社宅排水機制，並強化物管人員通報及處置模式，以因應極端氣候威脅。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBD159BF33CC56040B5F0654D472DFDF2F3B9F91770027D0D7E62F3DF37482B74208FC89D7F7EC79048','2026-09-28T10:12:56Z');
