INSERT INTO "fact" VALUES('interp:AQ14101265:p4b727b88dc','p4b727b88dc','interpellation','2024-09-26','{"councillors": ["吳世正"], "dept": "教育", "doc_no": "AQ14101265", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "民眾反映彩虹河濱公園免費網球場有團體長期占用並教球，多次向體育局申訴均未改善，請體育局加強晚間巡場並研擬防止占用免費球場之排隊措施，如掛拍實名登記制，以確保輪流使用免費場地之美意不被濫用。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBD159BF33CC56040B513FA3F932DAEE3BA4499F22AD804ACE662F3DF37482B74208250A1DD68DC9710','2026-09-28T10:12:56Z');
