INSERT INTO "fact" VALUES('interp:AQ14101172:p684c26bf24','p684c26bf24','interpellation','2024-07-15','{"councillors": ["李傅中武"], "dept": "民政", "doc_no": "AQ14101172", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "蔣萬安市長與本席攜手全力推動「全民原教」，讓國人更深入瞭解原住民族歷史、文化。每年8月1日為「原住民族日」，更是原住民族「入憲正名」最重要紀念日，爰建請原民會、交通局及臺北捷運公司共同研議於是日給予穿著原住民族傳統服飾者免費搭乘捷運系統及公車路網之優惠，並請將該議題提報「基北北桃合作交流平臺」合作方案辦理，以彰顯市府對於原住民族文化認同與尊重，促進國人瞭解原住民族歷史、文化，落實蔣萬安市長推動「全民原教」及「多元融合臺北」政策目標。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC47730E051144710864CE7A133CDAB0EE4174D42458EFF43684A0','2026-09-28T10:12:56Z');
