INSERT INTO "fact" VALUES('interp:AQ14101124:pccc2308c1b','pccc2308c1b','interpellation','2024-06-26','{"councillors": ["侯漢廷"], "dept": "教育", "doc_no": "AQ14101124", "doc_type": "書面質詢", "session": "第14屆第04次臨時大會", "term": 14, "title": "請將聽障學生納入「防空疏散避難教學影片（國中及高中版）」教學對象，莫讓宣導教學淪為形式口號。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC47734F7831E5323794D37A133CDAB0EE4174DAD47B927DDC086A','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101123:pcb793ad399','pcb793ad399','interpellation','2024-06-26','{"councillors": ["何孟樺"], "dept": "教育", "doc_no": "AQ14101123", "doc_type": "書面質詢", "session": "第14屆第04次臨時大會", "term": 14, "title": "市府現行對本市學生之午餐費用，各學制補助基準不一、補助規模不足，恐無法使學生安心就學，宜儘速修正「安心就學溫馨輔導實施計畫」，依各校實際午餐費用調升補助，以利提高本市學生整體競爭力。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC477395A0A089E3F2CF867A133CDAB0EE417427945323DE05612C','2026-09-28T10:12:56Z');
