INSERT INTO "fact" VALUES('interp:AQ14101121:pcb793ad399','pcb793ad399','interpellation','2024-06-25','{"councillors": ["何孟樺"], "dept": "教育", "doc_no": "AQ14101121", "doc_type": "書面質詢", "session": "第14屆第04次臨時大會", "term": 14, "title": "本市高級中等以下學校均應依相關規定登錄每日之營養午餐食材，然經查本席調查，竟有8所私立高中職未依規定登錄或登錄資料錯誤百出，教育局宜儘速調查並督導本市各學制學校登錄情形，以利學校供餐資訊透明化，衛生局亦應對各校執行全面稽查，若有違反相關條例情事，則應限期改善或處以罰鍰。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC47736A8AADE736EEB1D97A133CDAB0EE4174C584AE77D527DD82','2026-09-28T10:12:56Z');
