INSERT INTO "fact" VALUES('interp:AQ14101051:p67335d29b9','p67335d29b9','interpellation','2024-05-20','{"councillors": ["鍾沛君"], "dept": "財政建設", "doc_no": "AQ14101051", "doc_type": "書面質詢", "session": "第14屆第03次定期大會", "term": 14, "title": "行動支付為年輕世代的生活型態，也是我國邁向數位經濟的關鍵一步，北市府近年來推動公有零售市場、地下街及夜市交易型態導入多元化支付。但今年度的施政報告提到夜市的建置率仍較低，只有約72.9%，請說明目前遇到困難點與策進方案？同時市府須正視雖然傳統市場、夜市引進電子支付已久，依然有高達44%的民眾與攤商習慣繼續使用現金交易，請問有無更進一步促進轉型之對策？"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC477374A7C75DD66A1C56F79698F1B928EA5A3B71BA2C697B4C4F','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101050:p67335d29b9','p67335d29b9','interpellation','2024-05-20','{"councillors": ["鍾沛君"], "dept": "財政建設", "doc_no": "AQ14101050", "doc_type": "書面質詢", "session": "第14屆第03次定期大會", "term": 14, "title": "北投區媽祖窟、羅漢窟野溪溫泉由郝龍斌市長在103年以位於行水區危害安全為由拆除後，繼任的柯文哲市長105年初決策異地重建公共浴池，111年曾報載即將發包工程，惟今(113)年現場觀察仍無動工跡象。且許多民眾無視告示牌任意闖入行水區泡湯，讓現場雜亂也更危險，請產發局等主管機關說明目前公共浴室重建進度以及阻礙何在？"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC4773CCF3B8E9C1FEEF2BF79698F1B928EA5ACF591C2A98B15A03','2026-09-28T10:12:56Z');
