INSERT INTO "fact" VALUES('interp:AQ14100397:p684c26bf24','p684c26bf24','interpellation','2023-07-06','{"councillors": ["李傅中武"], "dept": "工務", "doc_no": "AQ14100397", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "臺北市立第一殯儀館拆除後，建請市府將該土地移交原民會管理使用並請原民會規劃設置臺北市原住民族文化觀光產業園區，以促進原住民族經濟產業發展，扶植原住民族青創產業，未來交由臺北市原住民族基金會負責經營管理，以保障本市原住民族生存發展，促進原住民族文化永續傳承，實現本市多元文化共存共榮之願景。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CFE0B7A51E9616A5C03ADA6385EC6173C8FA2A9B5C6611A3B640D3ABA0D5947CC','2026-09-28T10:12:56Z');
