INSERT INTO "fact" VALUES('interp:AQ14100382:p9ff03a516c','p9ff03a516c','interpellation','2023-07-03','{"councillors": ["林珍羽"], "dept": "警政衛生", "doc_no": "AQ14100382", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "臺北市政府警察局雖有編列預算採購義警、民防之服裝（夏服、冬服、冬大衣及裝備）、反光雨衣、皮鞋及安全帽等，惟同為值勤所需之反光背心、指揮棒、手電筒、哨子等必要裝備，卻須由義警、民防人員自費購置，除增加熱心服務者之負擔，亦影響民眾參與之意願。爰此，提案要求臺北市政府警察局應切實調查、統計義警、民防值勤設備需求，並每年編列預算購置之。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CFE0B7A51E9616A5C57D28AD8EFCB42FF8FA2A9B5C6611A3B4B4F2592D37B400A','2026-09-28T10:12:56Z');
