INSERT INTO "fact" VALUES('interp:AQ14100005:pa2aee439f8','pa2aee439f8','interpellation','2022-12-30','{"councillors": ["陳宥丞"], "dept": "教育", "doc_no": "AQ14100005", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "「避免跨年憾事發生！市府應提前因應國館施工維管！」針對往年跨年活動時國父紀念館園區內皆會聚集大量人潮觀賞101大樓煙火，但目前國父紀念館正在進行園區景觀改造工程，園區內有大範圍不得進入之工區，勢必會將人潮外溢至國父紀念館周邊，針對周邊人潮疏散、動線規劃、工區安全管制，市府與國父紀念館雙方是否有做好相關聯繫工作及配套措施，保障參與跨年活動民眾的人身安全?"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CFE0B7A51E9616A5CB13887F322AA940E186217F8DBC43E947B916E43F57D83A0','2026-09-28T10:12:56Z');
