INSERT INTO "fact" VALUES('interp:AQ14102405:pc164e1064f','pc164e1064f','interpellation','2026-06-10','{"councillors": ["陳怡君"], "dept": "工務", "doc_no": "AQ14102405", "doc_type": "書面質詢", "session": "第14屆第07次定期大會", "term": 14, "title": "台北市大同區鄭州路中興醫院旁人行道今早發生塌陷，巨大天坑導致鄰近變電箱位移倒塌，警消已介入處理，陳怡君議員擔心事故引發市民大道高架橋安全疑慮。由於天坑旁邊就是「市民大道高架橋」，陳怡君表示公共安全不容忽視，請市府單位積極做後續監測，保障市民用路安全。陳怡君呼籲市府採取科技手段，包含透地雷達巡檢、地體變形監測及地下水位觀測，對周邊地底進行地毯式安全檢查，防止地下掏空危機波及市民大道高架橋。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDF4D1149F9F07E2CC7439253861FC05FBE880062437AEC0F2D53A4C142158021654A7940CAA4F2443','2026-09-28T10:53:28Z');
