INSERT INTO "fact" VALUES('interp:AQ14102315:p62ab44979e','p62ab44979e','interpellation','2026-04-24','{"councillors": ["徐立信"], "dept": "教育", "doc_no": "AQ14102315", "doc_type": "書面質詢", "session": "第14屆第07次定期大會", "term": 14, "title": "關於民眾所提本市公共游泳池禁止穿鞋乙事，建請市府參考美國CDCMAHC等國際標準，全面檢討並修正禁止穿鞋政策。開放水上防滑襪、專用水鞋或室內防滑鞋、建立明確的管理與清潔機制，並優先在萬華等高齡區泳池試辦，保障長輩運動權益與安全，消除救生員與民眾之間的身分雙標，透明化特殊情況豁免條件，並加強現場人員訓練與考核。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDF4D1149F9F07E2CCAF964BD190863EF031803BCD771A0404D53A4C1421580216F7D71C068D9CB723','2026-09-28T10:53:28Z');
