INSERT INTO "fact" VALUES('interp:AQ14100912:pc164e1064f','pc164e1064f','interpellation','2024-03-14','{"councillors": ["陳怡君"], "dept": "工務", "doc_no": "AQ14100912", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "基泰大直賠償說明會帶風向：「不和解，可能就要走訴訟」陳怡君議員批誤導損鄰戶的權益！1.請市府針對損鄰金額及項目有疑義的，應重新鑑定，還住戶合理之賠償費用。2.基泰大直賠償說明會，該會議之風向誤導損鄰戶為「不和解，可能就要走訴訟」！此言論遭住戶怒批基泰毫無和解誠意！請蔣萬安市長及法務局，若住戶有團訟之需求，市府應責無旁貸直接協助訴訟。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CFE0B7A51E9616A5CE9C2FB47B38FF1A15F9CD4353581365A41553F8862820103','2026-09-28T10:53:28Z');
