INSERT INTO "fact" VALUES('profile:2022-local:p9ff03a516c','p9ff03a516c','profile','2022-11-26','{"education": ["• 台北市中山國小", "• 台北市衛理女中國中部", "• 台北市泰北高中廣告設計科", "• 台南應用科技大學美術系學士"], "election": "2022-local", "experience": ["• 臺北市政府 柯文哲市長隨行秘書", "• 臺北市政府 副發言人", "• 台灣民眾黨 創黨發言人", "• 三立電視台 行銷公關", "• 台北市議員林國成 特別助理", "• 銘傳大學管理學院 EMBA 碩士班"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p41a7902cc9','p41a7902cc9','profile','2022-11-26','{"education": ["銘傳大學新聞學系"], "election": "2022-local", "experience": ["• TVBS 主播", "• TVBS 主持人", "• TVBS 政治記者", "• 臺灣大學政治研究所（就讀中）"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:pdbfe9d98cc','pdbfe9d98cc','platform','2022-11-26','{"district_id": "tpe-council-04", "election": "2022-local", "office": "tpe_councilor", "text": "（一）守護長輩：爭取假牙、老花眼鏡及助聽器等各項補助。\n（二）婦女保障：補助婦女凍卵及各項健檢免費補助。\n（三）兒童教育：落實學齡前教育義務化。\n（四）青年政策：敦促市府設青年局，幫助青年圓夢，生涯發展。\n（五）完善醫療：提升市立聯合醫院成為醫學中心。\n（六）民生汐止：加速推動並增設捷運民生西路、重慶北路站。\n（七）大圓環站：增設捷運圓環站，活絡圓環商圈。\n（八）社子輕軌：爭取民族西路輕軌站，延伸路網至臺北車站。\n（九）淡水河岸：發展大稻埕水岸人文園區。\n（十）廢除一殯：爭取區域再造。\n（十一）文創平台：加強傳統藝術、文化與世界文創業交流。\n（十二）公園活化：完善花博、河濱、新生公園機能。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
