INSERT INTO "fact" VALUES('summary:14-05:pc164e1064f','pc164e1064f','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": null, "generator": null, "issues": [], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-05"], "dept": null, "doc_type": "市政總質詢", "group": 8, "heading": "市政總質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162", "videos": [{"date": "2025-06-05", "group": 8}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 8}]}, {"dates": ["2025-04-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 7, "heading": "警政衛生部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162", "videos": [{"date": "2025-04-15", "group": 7}]}, {"dates": ["2025-04-29"], "dept": "民政", "doc_type": "部門質詢", "group": 7, "heading": "民政部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2